import json,re,html,hashlib
from xml.etree import ElementTree as ET
s=json.load(open('source.json')); a=json.load(open('answer.json')); r=json.load(open('reference-targets.json'))
assert len(a)==len(s)==12
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
def plain(x):return re.sub(r'\\s+',' ',html.unescape(re.sub(r'<["'^>]*>'"',' ',x))).strip()
for x,y in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']:assert x[k]==y[k],(x['number'],k)
 key=x['code_id']+'|'+x['source_id']; sr=r['referrers'][key]
 assert hashlib.sha256(x['source_xml'].encode()).hexdigest()==sr['source_xml_sha256']
 assert hashlib.sha256(x['source_notes_xml'].encode()).hexdigest()==sr['source_notes_sha256']
 assert y['status'] in ['rewrite_draft','retained_unchanged']
 imp=y['substantive_impact']; assert imp['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(imp[k])>=40
 if y['status']=='retained_unchanged':assert y['proposed_xml'] is None and imp['classification']=='retained_necessary' and imp['effects']==[]
 else:
  root=ET.fromstring('<root>'+y['proposed_xml']+'</root>')
  for el in root.iter():
   if el.tag"'!='"'root':assert el.tag in allowed,(x['number'],el.tag)
   for attr,v in el.attrib.items():assert attr in ['rowspan','colspan'] and re.fullmatch('[0-9]+',v)
  for e in imp['effects']:
   assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
   assert len(e['source_quote'])>=12 and e['source_quote'] in plain(x['source_xml']),(x['number'],'source',e['source_quote'])
   assert len(e['proposed_quote'])>=12 and e['proposed_quote'] in plain(y['proposed_xml']),(x['number'],'proposed',e['proposed_quote'])
   assert e['unit'] in ['percent','euro','legal_duty','regime','calendar_days','working_days','financing','other']
   assert all(e.get(k) for k in ['kind','description','before','after','affected_population','conditions_and_transition','replacement_or_new_burdens'])
 if x['benefit_check_required']:assert len(y['benefit_review'])>=100
 checks=y['reference_checks']; assert len(checks)==len(set(c['target_key'] for c in checks))
 assert set(r['requirements'][key])<=set(c['target_key'] for c in checks)
 for c in checks:assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80
 if y.get('change_type')=='normative_reduction':assert y['reform_policy_id']=='editorial_direction_2026_10_19' and all(len(z)>=30 for z in y['removed_provisions'])
 if imp['classification']=='mixed':assert any(e['kind'] not in ['coordination','relief_preserved'] for e in imp['effects'])
 print(y['number'],y['status'],imp['classification'],'effects:',', '.join(e['kind'] for e in imp['effects']), 'references:',len(checks))
print('Contrôles structurels, citations exactes et empreintes : OK. Aucune validation juridique déduite.')
PY"

